import assert from 'node:assert/strict';
import {execFileSync} from 'node:child_process';
import {readFile} from 'node:fs/promises';
import {chromium} from 'playwright';
import nodemailer from 'nodemailer';
import {recoveryHandler} from '../../admin-recovery/handler.mjs';
import {sandboxLogin} from '../../admin-recovery/sandbox/login-handler.mjs';
import {buildSandbox} from '../../scripts/build-recovery-sandbox.mjs';

const base=process.env.API_URL,anon=process.env.ANON_KEY,service=process.env.SERVICE_ROLE_KEY,dburl=process.env.DB_URL;
assert.match(base,/^http:\/\/(localhost|127\.0\.0\.1):\d+$/);assert.match(dburl,/^postgres(?:ql)?:\/\/postgres:[^@]+@(localhost|127\.0\.0\.1):\d+\/postgres$/);
const email='combined-probe@example.test',oldPassword='Local-Old-Password-902!',newPassword='Local-New-Password-435!',origin='https://probe.invalid',supabase='https://abcdefghijklmnopqrst.supabase.co';
async function api(path,{body,token=service,key=service,method='POST'}={}){const r=await fetch(base+path,{method,headers:{apikey:key,authorization:'Bearer '+token,'content-type':'application/json'},...(body===undefined?{}:{body:JSON.stringify(body)})});const t=await r.text();if(!r.ok)throw Error(path+' status '+r.status);return t?JSON.parse(t):{};}
const owner=await api('/auth/v1/admin/users',{body:{email,password:oldPassword,email_confirm:true}});const setup=await readFile('admin-recovery/sandbox/prepare-isolated.sql','utf8');execFileSync('psql',[dburl,'-X','-v','ON_ERROR_STOP=1','-q'],{input:`select set_config('ispovesti.sandbox_approval','isolated-admin-recovery-v1',false),set_config('ispovesti.sandbox_owner_uid','${owner.id}',false);\n${setup}`,stdio:['pipe','pipe','pipe']});await new Promise(r=>setTimeout(r,1500));
const rpc=(name,args)=>api('/rest/v1/rpc/'+name,{body:args});const passwordLogin=password=>api('/auth/v1/token?grant_type=password',{key:anon,token:anon,body:{email,password}});
const oldSession=await passwordLogin(oldPassword);const sid=JSON.parse(Buffer.from(oldSession.access_token.split('.')[1],'base64url')).session_id;
const smtp=nodemailer.createTransport({host:'127.0.0.1',port:54325,secure:false,ignoreTLS:true});
let captchaRequests=0;
const recovery=recoveryHandler({config:{enabled:true,authResetApproved:true,ownerUID:owner.id,linkURL:origin+'/test/admin-recovery.html'},store:(action,args)=>rpc('recovery_sandbox_admin_recovery',{p_action:action,p_args:args}),auth:{getUser:id=>api('/auth/v1/admin/users/'+id,{method:'GET'}),updatePassword:(id,password)=>api('/auth/v1/admin/users/'+id,{method:'PUT',body:{password}}),revokeAll:async(id,e,password)=>{const s=await passwordLogin(password);assert.equal(s.user.id,id);await api('/auth/v1/logout?scope=global',{key:anon,token:s.access_token,body:{}})}},captcha:{verify:async token=>{captchaRequests++;const r=await fetch('https://challenges.cloudflare.com/turnstile/v0/siteverify',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({secret:'1x0000000000000000000000000000000AA',response:token}),signal:AbortSignal.timeout(15000)});return r.ok&&(await r.json()).success===true}},mail:{send:async({to,link})=>smtp.sendMail({from:'sandbox@example.test',to,subject:'Recovery test',text:link})},delay:async()=>{}});
const login=sandboxLogin({origin,ownerUID:owner.id,rpc:(kind,uid,action,args)=>rpc(kind==='email'?'recovery_sandbox_admin_email':'recovery_sandbox_login',{p_uid:uid,p_action:action,p_args:args}),auth:{getUser:jwt=>api('/auth/v1/user',{method:'GET',token:jwt,key:anon}),sendOtp:e=>api('/auth/v1/otp',{key:anon,token:anon,body:{email:e,create_user:false}}),verifyOtp:async(e,code)=>{try{return (await api('/auth/v1/verify',{key:anon,token:anon,body:{email:e,token:code,type:'email'}})).user}catch{return null}}}});
await buildSandbox();const browser=await chromium.launch({headless:true});const page=await browser.newPage({viewport:{width:390,height:844}});
async function message(subject){for(let i=0;i<15;i++){const list=await(await fetch('http://127.0.0.1:54324/api/v1/messages')).json();const m=list.messages?.find(x=>x.Subject===subject);if(m)return (await(await fetch('http://127.0.0.1:54324/api/v1/message/'+m.ID)).json());await new Promise(r=>setTimeout(r,400));}throw Error('Expected test email missing: '+subject)}
try{
 await page.route('https://probe.invalid/**',async route=>{const pathname=new URL(route.request().url()).pathname;if(pathname==='/test/config.js')return route.fulfill({contentType:'application/javascript',body:`window.ISPOVESTI_CONFIG=${JSON.stringify({mode:'recovery-sandbox',configured:true,projectRef:'abcdefghijklmnopqrst',supabaseUrl:supabase,siteOrigin:origin,publishableKey:'sb_publishable_test',recoverySitekey:'1x00000000000000000000AA'})};`});if(!/^\/test\/[a-zA-Z0-9_./-]+$/.test(pathname)||pathname.includes('..'))return route.fulfill({status:404,body:''});try{const data=await readFile('.recovery-sandbox-review'+pathname);const ext=pathname.split('.').pop();return route.fulfill({status:200,contentType:ext==='html'?'text/html':ext==='css'?'text/css':'application/javascript',body:data})}catch{return route.fulfill({status:404,body:''})}});
 await page.route(supabase+'/**',async route=>{const req=route.request();const url=new URL(req.url());if(req.method()==='OPTIONS')return route.fulfill({status:204,headers:{'access-control-allow-origin':origin,'access-control-allow-headers':'authorization,apikey,content-type,x-client-info','access-control-allow-methods':'GET,POST,PUT,OPTIONS'}});if(url.pathname.startsWith('/functions/')){const h=url.pathname.endsWith('admin-recovery-isolated-api')?recovery:login;const headers={origin,authorization:req.headers().authorization||'',apikey:'local', 'content-type':'application/json'};const out=await h(new Request(origin+'/api',{method:'POST',headers,body:req.postData()||'{}'}));return route.fulfill({status:out.status,body:await out.text(),headers:{'content-type':'application/json','access-control-allow-origin':origin}})}const headers={...req.headers(),apikey:anon};if(headers.authorization==='Bearer sb_publishable_test')headers.authorization='Bearer '+anon;delete headers.host;const response=await fetch(base+url.pathname+url.search,{method:req.method(),headers,...(['GET','HEAD'].includes(req.method())?{}:{body:req.postData()})});return route.fulfill({status:response.status,body:await response.text(),headers:{'content-type':'application/json','access-control-allow-origin':origin,'access-control-allow-headers':'authorization,apikey,content-type,x-client-info'}})});
 await page.goto(origin+'/test/admin.html');await page.locator('#forgot-password').click();await page.locator('input[autocomplete=email]').fill(email);await page.getByRole('button',{name:'Pošalji link za oporavak'}).click();await page.getByText(/Ako je e-mail administratorski/).waitFor({timeout:45000});assert.equal(captchaRequests,1);
 const mail=await message('Recovery test');const link=(mail.Text||mail.HTML).match(/https:\/\/probe\.invalid\/test\/admin-recovery\.html#token=[A-Za-z0-9_-]+/)?.[0];assert.ok(link,'Recovery link missing from Mailpit');
 await page.goto(link);assert.equal(new URL(page.url()).hash,'');await page.locator('#new-password').fill(newPassword);await page.locator('#repeat-password').fill(newPassword);await page.getByRole('button',{name:'Sačuvaj novu lozinku'}).click();await page.getByText(/Lozinka je promijenjena/).waitFor();await assert.rejects(passwordLogin(oldPassword));await assert.rejects(rpc('recovery_sandbox_login',{p_uid:owner.id,p_action:'session',p_args:{_session_id:sid}}));
 await page.getByRole('link',{name:'Nazad na administratorsku prijavu'}).click();await page.locator('#email').fill(email);await page.locator('#password').fill(newPassword);await page.locator('#login-form button').click();await page.locator('#email-send').waitFor({state:'visible'});assert.equal(await page.locator('#tools').isHidden(),true);await page.locator('#email-send').click();await page.locator('#email-code').waitFor({state:'visible'});const otp=await message('Local OTP');const code=(otp.Text||otp.HTML).match(/\b\d{6}\b/)?.[0];assert.ok(code,'OTP missing');await page.locator('#email-code').fill(code);await page.getByRole('button',{name:'Potvrdi pristup'}).click();await page.locator('#tools').waitFor({state:'visible'});console.log('PASS integrated mobile browser, local Supabase Auth/SQL, Mailpit SMTP, Cloudflare dummy validation and fresh OTP.');
}finally{await browser.close();smtp.close()}
